package com.hmdp.ai.runtime.retrieval;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.artifact.Citation;import com.hmdp.ai.domain.knowledge.KnowledgeChunk;import org.springframework.stereotype.Component;
@Component public class CitationBuilder {private final ObjectMapper mapper;public CitationBuilder(ObjectMapper mapper){this.mapper=mapper;}public Citation build(KnowledgeChunk c,double score){String title=c.getDocumentId();try{JsonNode metadata=mapper.readTree(c.getMetadataJson());title=metadata.path("title").asText(title);}catch(Exception ignored){}String row=c.getRowStart()==null?null:(c.getRowEnd()==null?String.valueOf(c.getRowStart()):c.getRowStart()+"-"+c.getRowEnd());String preview=c.getContent().length()<=240?c.getContent():c.getContent().substring(0,240)+"...";return new Citation("citation-"+c.getId(),c.getKnowledgeBaseId(),c.getDocumentId(),c.getDocumentVersion(),c.getId(),title,c.getSourceType(),c.getPage(),c.getSection(),c.getSheet(),row,score,preview);}}
